/**
 * Parses a comma-separated assertion value string using CSV-style quoting rules.
 *
 * - Fields wrapped in double quotes are treated as a single token even when they
 *   contain commas.
 * - Whitespace (including tabs) surrounding fields is ignored and does not produce
 *   spurious empty tokens; empty unquoted fields (e.g. from consecutive commas) are
 *   dropped.
 * - Inside a quoted field, two consecutive double quotes (`""`) represent a single
 *   literal double quote, a backslash-escaped quote (`\"`) represents a literal
 *   double quote, and a backslash-escaped backslash (`\\`) represents a literal
 *   backslash. Any other backslash is kept literally.
 * - An explicitly quoted empty string (`""`) yields an empty token, which is
 *   contained in any string and therefore always matches.
 */
function parseContainsValue(value: string): string[] {
  const tokens: string[] = [];
  const length = value.length;
  let i = 0;

  const isWhitespace = (char: string) => char !== ',' && /\s/.test(char);

  while (i < length) {
    // Skip leading whitespace before a field.
    while (i < length && isWhitespace(value[i])) {
      i++;
    }
    if (i >= length) {
      break;
    }
    // Empty unquoted field (consecutive commas): drop it.
    if (value[i] === ',') {
      i++;
      continue;
    }

    if (value[i] === '"') {
      // Quoted field.
      i++; // consume opening quote
      let token = '';
      while (i < length) {
        const char = value[i];
        if (char === '\\') {
          const next = value[i + 1];
          if (next === '"') {
            token += '"';
            i += 2;
            continue;
          }
          if (next === '\\') {
            token += '\\';
            i += 2;
            continue;
          }
          // Backslash before any other character is kept literally.
          token += '\\';
          i++;
          continue;
        }
        if (char === '"') {
          if (value[i + 1] === '"') {
            // Doubled quote -> literal quote.
            token += '"';
            i += 2;
            continue;
          }
          // Closing quote.
          i++;
          break;
        }
        token += char;
        i++;
      }
      // Skip any trailing content until the next field separator.
      while (i < length && value[i] !== ',') {
        i++;
      }
      if (i < length && value[i] === ',') {
        i++;
      }
      tokens.push(token);
    } else {
      // Unquoted field: read until the next comma, then trim surrounding whitespace.
      let raw = '';
      while (i < length && value[i] !== ',') {
        raw += value[i];
        i++;
      }
      if (i < length && value[i] === ',') {
        i++;
